# PREL40 lab files update for the Skillable VM.
# Generated by scripts/publish-vm-update.mjs from scripts/vm-update.template.ps1. Edit the template, not the generated copy.
# Runs with "irm <url> | iex", so it must never call exit. Works on Windows PowerShell 5.1 and PowerShell 7.
# Output is ASCII only: Windows PowerShell 5.1 garbles emoji in console output.

& {
    $ErrorActionPreference = 'Stop'

    $build = @'
__BUILD_JSON__
'@ | ConvertFrom-Json

    $payload = @'
__PAYLOAD_BASE64__
'@

    # Environment overrides exist for testing the script away from the VM.
    $labRoot = if ($env:PREL40_LABFILES) { $env:PREL40_LABFILES } else { 'C:\LabFiles' }
    $copilotHome = if ($env:PREL40_COPILOT_HOME) { $env:PREL40_COPILOT_HOME } elseif ($env:COPILOT_HOME) { $env:COPILOT_HOME } else { Join-Path $HOME '.copilot' }

    $templateTarget = [IO.Path]::Combine($labRoot, 'template', 'home-loan-desk')
    $dataTarget = Join-Path $labRoot 'data'
    $checkpointsTarget = Join-Path $labRoot 'checkpoints'
    $skillsRoot = Join-Path $copilotHome 'skills'
    $skills = @('check-setup', 'lab-checkpoint')
    # Skills from earlier updates that were renamed or removed.
    $oldSkills = @('lab-check-setup')
    $settingsPath = Join-Path $copilotHome 'settings.json'
    $versionPath = Join-Path $labRoot 'lab-files.json'

    $results = New-Object System.Collections.Generic.List[object]

    function Add-Result([string]$Group, [string]$Target, [string]$Status, [string]$Details) {
        $results.Add([pscustomobject]@{ Group = $Group; Status = $Status; Target = $Target; Details = $Details })
    }

    function Invoke-Update([string]$Group, [string]$Target, [scriptblock]$Action) {
        try {
            Add-Result $Group $Target 'OK' ([string](& $Action))
        } catch {
            Add-Result $Group $Target 'FAILED' $_.Exception.Message
        }
    }

    function Get-FileCount([string]$Path) {
        @(Get-ChildItem -LiteralPath $Path -Recurse -File -Force).Count
    }

    function Copy-Folder([string]$Source, [string]$Destination) {
        if (-not (Test-Path -LiteralPath $Source -PathType Container)) { throw "Missing from the package: $Source" }
        if (Test-Path -LiteralPath $Destination) { Remove-Item -LiteralPath $Destination -Recurse -Force }
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Destination) | Out-Null
        Copy-Item -LiteralPath $Source -Destination $Destination -Recurse -Force
        Get-FileCount $Destination
    }

    function Set-PermissionMode([string]$Path, [string]$Mode) {
        $settings = $null
        if (Test-Path -LiteralPath $Path -PathType Leaf) {
            $raw = [IO.File]::ReadAllText($Path)
            if ($raw.Trim()) {
                try { $settings = $raw | ConvertFrom-Json }
                catch { throw "settings.json isn't plain JSON, so it was left unchanged. Set the default permission mode to allow-all in the GitHub Copilot app settings." }
            }
        }
        if (-not $settings) { $settings = New-Object psobject }
        $current = $settings.PSObject.Properties['defaultPermissionMode']
        if ($current -and $current.Value -eq $Mode) { return "Already $Mode" }
        if ($current) { $current.Value = $Mode } else { $settings | Add-Member -NotePropertyName 'defaultPermissionMode' -NotePropertyValue $Mode }
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Path) | Out-Null
        [IO.File]::WriteAllText($Path, ($settings | ConvertTo-Json -Depth 32), (New-Object Text.UTF8Encoding $false))
        "Set to $Mode"
    }

    Write-Host ''
    Write-Host 'PREL40 lab files update'
    $suffix = if ($build.dirty) { ' with local changes' } else { '' }
    Write-Host "Build $($build.shortCommit)$suffix, built $($build.builtAt)"
    Write-Host ''

    $work = Join-Path ([IO.Path]::GetTempPath()) ('prel40-update-' + [guid]::NewGuid().ToString('N'))
    $staging = Join-Path $work 'package'
    try {
        $unpackError = $null
        try {
            New-Item -ItemType Directory -Force -Path $work | Out-Null
            $zipPath = Join-Path $work 'lab-files.zip'
            [IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($payload))
            $hash = (Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash
            if ($hash -ne $build.sha256) { throw 'The download is corrupted (checksum mismatch). Run the command again.' }
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            [IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $staging)
        } catch {
            $unpackError = "Package not unpacked: $($_.Exception.Message)"
        }

        if ($unpackError) {
            Add-Result 'Rayfin template' $templateTarget 'FAILED' $unpackError
            Add-Result 'Lab data' $dataTarget 'FAILED' $unpackError
            Add-Result 'Checkpoints' $checkpointsTarget 'FAILED' $unpackError
            foreach ($skill in $skills) { Add-Result "$skill skill" (Join-Path $skillsRoot $skill) 'FAILED' $unpackError }
        } else {
            Invoke-Update 'Rayfin template' $templateTarget {
                "$(Copy-Folder ([IO.Path]::Combine($staging, 'template', 'home-loan-desk')) $templateTarget) files"
            }
            Invoke-Update 'Lab data' $dataTarget {
                New-Item -ItemType Directory -Force -Path $dataTarget | Out-Null
                Copy-Item -LiteralPath ([IO.Path]::Combine($staging, 'data', 'portfolio-seed.sql')) -Destination $dataTarget -Force
                $samples = Copy-Folder ([IO.Path]::Combine($staging, 'data', 'samples')) (Join-Path $dataTarget 'samples')
                "portfolio-seed.sql and $samples sample files"
            }
            Invoke-Update 'Checkpoints' $checkpointsTarget {
                "$(Copy-Folder (Join-Path $staging 'checkpoints') $checkpointsTarget) files (run npm install before use)"
            }
            foreach ($skill in $skills) {
                $skillTarget = Join-Path $skillsRoot $skill
                Invoke-Update "$skill skill" $skillTarget {
                    "$(Copy-Folder ([IO.Path]::Combine($staging, 'skills', $skill)) $skillTarget) files"
                }
            }
            foreach ($skill in $oldSkills) {
                $oldTarget = Join-Path $skillsRoot $skill
                if (Test-Path -LiteralPath $oldTarget) {
                    Invoke-Update "$skill skill" $oldTarget { Remove-Item -LiteralPath $oldTarget -Recurse -Force; 'Removed (replaced by a newer skill)' }
                }
            }
        }

        Invoke-Update 'Copilot permissions' $settingsPath { Set-PermissionMode $settingsPath 'allow-all' }

        if ($unpackError) {
            Add-Result 'Version stamp' $versionPath 'FAILED' 'Skipped: package not unpacked.'
        } else {
            Invoke-Update 'Version stamp' $versionPath {
                New-Item -ItemType Directory -Force -Path $labRoot | Out-Null
                Copy-Item -LiteralPath (Join-Path $staging 'manifest.json') -Destination $versionPath -Force
                $build.shortCommit
            }
        }
    } finally {
        if (Test-Path -LiteralPath $work) { Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue }
    }

    $results | Format-Table -AutoSize -Wrap | Out-String -Width 4096 | Write-Host

    $failed = @($results | Where-Object { $_.Status -ne 'OK' }).Count
    if ($failed -eq 0) {
        Write-Host 'All updates succeeded. Restart the GitHub Copilot app, then run /check-setup in a new chat.' -ForegroundColor Green
    } else {
        Write-Host "$failed update(s) failed. Fix the cause shown above, then run the same command again." -ForegroundColor Red
    }
    Write-Host ''
}
